function defaultWriteFile(path, content) {
    return file_write(path, content);
}

function defaultDeleteFile(path) {
    try {
        file_delete({ path: path });
    } catch (e) {
        // Best-effort cleanup only — a leftover temp PR-body file is not fatal on an
        // ephemeral CI runner, but it does dirty the tree on a reused local-teammate
        // checkout (js/../scripts/run-teammate-local.sh refuses to run against a
        // dirty tree), so we still try.
    }
}

// ── Closes line (gh-737) ────────────────────────────────────────────────────
// The merge bot (awf factory-merge-trigger) links approved issues to PRs ONLY
// via 'Closes #N' in the PR body (or branch 'N-*'). Factory-created PRs built
// from the response.md template carried no Closes line, so the bot reported
// 'no linked open PR' for every approved issue and merged nothing
// (merged=0 skipped=4, live fa 2026-10-05). Every PR the pack creates must
// therefore carry the canonical line by construction. Bot-side awf#19 also
// accepts Fixes/Part-of, but the pack still emits canonical Closes — a
// non-canonical keyword never substitutes for it.
var GITHUB_ISSUE_KEY = /^gh-\d+$/i;

/**
 * Extracts the trailing issue number from a ticket key (gh-737 → '737',
 * PROJ-123 → '123'). Returns null when the key carries no digits.
 */
function extractIssueNumber(ticketKey) {
    var m = /(\d+)\s*$/.exec(String(ticketKey || '').trim());
    return m ? m[1] : null;
}

/**
 * Guarantees the body contains the canonical 'Closes #N' line for the ticket.
 * Idempotent: a body that already closes the same issue is left untouched;
 * any other keyword (Fixes/Part-of) still gets the canonical line added.
 * Keys that are not GitHub router keys (gh-N) leave the body unchanged.
 */
function ensureClosesLine(body, ticketKey) {
    // Only GitHub router keys (gh-N) map to a closeable GitHub issue; tracker keys
    // such as PROJ-123 would produce a bogus 'Closes #123' link.
    if (!GITHUB_ISSUE_KEY.test(String(ticketKey || '').trim())) return body;
    var num = extractIssueNumber(ticketKey);
    if (!num) return body;

    var text = body === null || body === undefined ? '' : String(body);
    if (new RegExp('\\bCloses\\s+#?' + num + '\\b', 'i').test(text)) return text;

    return 'Closes #' + num + '\n' + text;
}

